(function () {
  'use strict';
  const C=window.MH_CATALOG, E=window.MHEngine, T=window.MHTable, D=window.MHDeckTools;
  const main=document.getElementById('site'), modal=document.getElementById('site-modal');
  if(!C||!E||!T||!D||!window.MHProfiles||!window.MHP2P||!window.MHGameUI||!window.MHMatch){main.innerHTML='<div class="loading"><h1>La Guilde se prépare</h1><p>Un fichier n’a pas pu être chargé. Recharge la page pour réessayer.</p></div>';return;}
  const store=MHProfiles.createStore(), byId=new Map(C.cards.map(c=>[c.id,c])), supported=new Set(E.SUPPORTED_IDS), clone=v=>JSON.parse(JSON.stringify(v));
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const colors={Vert:'#5a944f',Jaune:'#d2b654',Orange:'#cf8d42',Rouge:'#b8614d',Violet:'#9474af',Bleu:'#659cbb',Marron:'#957559'};
  const labels={large:'Grands Monstres',small:'Petits Monstres',hunter:'Chasseurs',item:'Objets',technique:'Techniques',chief:'Chefs de chasse',token:'Jetons'};
  let profile=null,decks=[],draft=null,game=null,gameUI=null,peer=null,hostMatch=null,revision=-1,toastTimer,searchTimer;
  const ui={route:'accueil',search:'',color:'',type:'',cost:'',sort:'id',extension:'',compatible:true,deckId:null,mode:'auto',leftDeck:'',rightDeck:'',network:'internet',onlineStatus:'idle',onlineLabel:'Aucune connexion en cours.',offer:'',answer:'',offerInput:'',answerInput:'',busy:false,turnUrls:'',turnUser:'',turnPassword:'',authMode:'login',onlineRole:null,onlineMode:'manual'};
  function toast(text,error=false){const t=document.getElementById('site-toast');t.textContent=text;t.className='toast'+(error?' error':'');t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,5000);}
  function refreshProfile(){try{profile=store.current();decks=profile?store.listDecks():[];}catch(err){profile=null;decks=[];toast(err.message,true);}}
  function route(name){if(location.hash==='#'+name){ui.route=name;render();}else location.hash=name;}
  function heading(title,sub,buttons=''){return `<div class="site-page-heading"><div><div class="kicker">La Guilde des chasseurs</div><h1>${title}</h1><p>${sub}</p></div>${buttons?`<div class="builder-toolbar">${buttons}</div>`:''}</div>`;}
  function profileControl(){document.getElementById('profile-control').innerHTML=profile?`<button class="profile-button" data-do="account"><span class="profile-avatar">${esc(profile.username.slice(0,2).toUpperCase())}</span>${esc(profile.username)}<span aria-hidden="true">⌄</span></button>`:'<button class="button primary" data-do="account">Se connecter</button>';}
  function validation(d){return D.validateDeck(d,C,{supportedIds:E.SUPPORTED_IDS});}
  function deckOptions(selected){return decks.map(d=>`<option value="${esc(d.id)}" ${d.id===selected?'selected':''}>${esc(d.name)} · ${d.cards.length}/50</option>`).join('');}
  function getDeck(id){return decks.find(d=>d.id===id)||null;}
  function cardStatus(c){return supported.has(c.id)?'Auto':'Table libre';}
  function savedDeck(d){const chief=byId.get(d.chiefId),v=validation(d);return `<article class="saved-deck"><div class="deck-art"><img loading="lazy" src="${chief?.image||'assets/cards/001.webp'}" alt=""><div class="deck-art-title"><h3>${esc(d.name)}</h3><p>${esc(chief?.name||'Choisir un Chef')}</p></div></div><div class="deck-card-body"><span class="${v.valid?'badge-valid':'badge-draft'}">${d.cards.length}/50 cartes · ${v.valid?'Prêt à jouer':'Brouillon'}</span><button class="button small" data-edit-deck="${esc(d.id)}">Ouvrir →</button></div></article>`;}
  function home(){return `<div class="site-main"><section class="hero"><div class="hero-copy"><div class="hero-badge">✦ BIENVENUE À LA GUILDE</div><h1>Prépare ton deck.<br><em>Entre dans la chasse.</em></h1><p>Retrouve tes cartes, construis ta stratégie et partage une partie de Monster Hunter TCG avec un ami.</p><div class="hero-actions"><button class="button primary" data-go="jouer">Commencer à jouer <span>↗</span></button><button class="button quiet" data-go="decks">Construire un deck</button></div></div><div class="hero-art" aria-label="Cartes du jeu"><img src="assets/cards/031.webp" alt="Velocidrome, chef des faibles"><img src="assets/cards/173.webp" alt="Basarios, gisement ambulant"><img src="assets/cards/014.webp" alt="Zora, apaisé par la forêt"><div class="hero-stat"><div><b>203</b><span>Cartes à découvrir</span></div><div><b>7</b><span>Couleurs</span></div><div><b>6</b><span>Points pour gagner</span></div></div></div></section><div class="quick-grid"><button class="quick-card" data-go="test"><span class="quick-icon">♧</span><div><h2>Teste ta stratégie</h2><p>Prends la main sur les deux camps,<br>à ton rythme.</p></div><span class="arrow">↗</span></button><button class="quick-card" data-go="enligne"><span class="quick-icon">⇄</span><div><h2>Joue avec un ami</h2><p>Une invitation, une connexion directe,<br>et la chasse peut commencer.</p></div><span class="arrow">↗</span></button><button class="quick-card" data-go="cartes"><span class="quick-icon">▧</span><div><h2>Explore les cartes</h2><p>Noms, armes, espèces et biomes :<br>trouve ta prochaine synergie.</p></div><span class="arrow">↗</span></button></div><div class="section-heading"><div><h2>${profile?'Tes decks':'Ton prochain deck t’attend'}</h2><p>${profile?'Retrouve tes préparations, enregistrées dans ce navigateur.':'Un pseudo, un mot de passe. Aucun email.'}</p></div>${profile?'<button data-go="decks">Tous mes decks →</button>':''}</div>${profile?`<div class="saved-decks-grid">${decks.slice(0,2).map(savedDeck).join('')}<button class="deck-create" data-do="new-deck"><span>+</span>Créer un nouveau deck</button></div>`:`<div class="guest-line"><div><h3>Rejoins la Guilde</h3><p>Crée ton profil local pour conserver tes decks et lancer une partie.<br>Ton pseudo et tes decks restent dans ce navigateur.</p></div><button class="button primary" data-do="register">Créer mon profil</button></div>`}${game?'<p class="info-line"><button class="text-button" data-go="table">Reprendre la table ouverte →</button></p>':''}<p class="info-line">✧ Extension actuelle : MhFG. Les sauvegardes restent sur cet appareil ; tu peux exporter tes decks pour les emporter.</p></div>`;}
  function gate(title){return `<div class="site-main">${heading(title,'Ta Guilde, tes decks, tes parties.')}<section class="empty-profile"><span class="crest">✦</span><h2>Ton aventure commence ici</h2><p>Crée un profil avec un pseudo et un mot de passe pour enregistrer tes decks dans ce navigateur. Aucun email n’est demandé.</p><button class="button primary" data-do="register">Créer mon profil</button><p style="margin-top:17px;margin-bottom:0"><button class="text-button" data-do="account">J’ai déjà un profil sur ce navigateur</button></p></section></div>`;}
  function filters(builder){return `<div class="site-filter-panel"><div class="search-row"><div class="site-search"><input id="card-search" type="search" placeholder="Un nom, un type, une arme… Rathian, Lance, Dragon Ancien" aria-label="Rechercher par nom, type ou sous-type" value="${esc(ui.search)}"></div><select id="extension-filter" aria-label="Extension"><option value="">Toutes les extensions</option>${D.getExtensions(C).map(e=>`<option value="${e.id}" ${ui.extension===e.id?'selected':''}>${esc(e.name)} · ${e.count} cartes</option>`).join('')}</select><select id="sort-filter" aria-label="Trier les cartes">${[['id','Numéro de carte'],['name','Nom A → Z'],['cost','Coût croissant'],['cost-desc','Coût décroissant'],['force','Force'],['hp','Points de vie']].map(([id,l])=>`<option value="${id}" ${ui.sort===id?'selected':''}>${l}</option>`).join('')}</select></div><div class="filters-row"><div class="color-filters" aria-label="Couleurs"><button class="color-button ${!ui.color?'active':''}" data-color="" aria-label="Toutes les couleurs">Tout</button>${Object.entries(colors).map(([name,color])=>`<button class="color-button ${ui.color===name?'active':''}" style="--biome:${color}" data-color="${name}" aria-label="Couleur ${name}" title="${name}"><span></span></button>`).join('')}</div><select id="type-filter" aria-label="Type de carte"><option value="">Tous les types</option>${Object.entries(labels).filter(([id])=>!builder||!['chief','token'].includes(id)).map(([id,label])=>`<option value="${id}" ${ui.type===id?'selected':''}>${label}</option>`).join('')}</select><select id="cost-filter" aria-label="Coût de la carte"><option value="">Tous les coûts</option>${[0,1,2,3,4,5,6,'7+'].map(n=>`<option value="${n}" ${String(ui.cost)===String(n)&&ui.cost!==''?'selected':''}>${n} ration${n===1?'':'s'}</option>`).join('')}</select>${builder?`<label class="filter-check"><input id="compatible-filter" type="checkbox" ${ui.compatible?'checked':''}> Couleurs de mon Chef</label>`:'<span class="filter-check">203 cartes · 2 jetons</span>'}</div></div>`;}
  function filtered(builder){return D.filterCards(C,{search:ui.search,extension:ui.extension,color:ui.color,type:ui.type,cost:ui.cost===''?undefined:ui.cost,sort:ui.sort,compatibleColors:builder&&ui.compatible?byId.get(draft?.chiefId)?.colors:undefined,includeTokens:!builder}).filter(c=>!builder||!['chief','token'].includes(c.type));}
  function tile(c,builder){const quantity=builder?draft.cards.filter(id=>id===c.id).length:0;const isCompatible=!builder||c.colors.every(color=>byId.get(draft.chiefId)?.colors.includes(color));return `<article class="card-tile"><button class="card-image-button" data-detail="${c.id}" aria-label="Lire ${esc(c.name)}"><img loading="lazy" src="${c.image}" alt="${esc(c.name)}"><span class="tile-tag ${supported.has(c.id)?'':'free'}">${cardStatus(c)}</span></button><h3>${esc(c.name)}</h3><p>${esc(c.typeLabel)}${c.subtypes.length?' · '+esc(c.subtypes.join(' / ')):''}<br>MhFG · ${c.id}</p>${builder?`<div class="tile-counter"><span>${quantity}/3</span><div>${quantity?`<button data-minus="${c.id}" aria-label="Retirer ${esc(c.name)}">−</button>`:''}<button class="add" data-plus="${c.id}" ${quantity>=3||draft.cards.length>=50||!isCompatible?'disabled':''} aria-label="Ajouter ${esc(c.name)}">+ Ajouter</button></div></div>`:''}</article>`;}
  function library(){const cards=filtered(false);return `<div class="site-main">${heading('La bibliothèque','Toutes les cartes actuelles. Recherche un nom, un type ou un sous-type.')}${filters(false)}<div class="result-line"><span>${cards.length} résultat${cards.length>1?'s':''}</span><span>Auto : effet programmé · Table libre : effet résolu par les joueurs</span></div><div class="card-grid">${cards.map(c=>tile(c,false)).join('')||'<p class="no-result">Aucune carte ne correspond à ces critères.</p>'}</div></div>`;}
  function loadDraft(id){const d=getDeck(id)||decks[0];draft=d?clone(d):null;ui.deckId=d?.id||null;}
  function saveDraft(silent=true){if(!draft)return;try{draft=store.saveDeck(draft);ui.deckId=draft.id;decks=store.listDecks();if(!silent)toast('Ton deck est enregistré dans ce navigateur.');}catch(err){toast(err.message,true);}}
  function newDeck(){if(!requireProfile())return;try{draft=store.saveDeck({name:'Nouveau deck',chiefId:'202',cards:[]});decks=store.listDecks();ui.deckId=draft.id;ui.search='';ui.color='';ui.type='';route('decks');}catch(err){toast(err.message,true);}}
  function builder(){if(!profile)return gate('Le deck builder');if(!draft||!getDeck(draft.id))loadDraft(ui.deckId);if(!draft)return `<div class="site-main">${heading('Le deck builder','Prépare un deck de 50 cartes autour d’un Chef.')}<section class="empty-profile"><h2>Ton premier deck</h2><p>Choisis un Chef, puis ajoute jusqu’à trois exemplaires de chaque carte de ses couleurs.</p><button class="button primary" data-do="new-deck">Créer un deck</button><button class="button quiet" data-do="starter-decks">Ajouter les decks de départ</button></section></div>`;const v=validation(draft),chief=byId.get(draft.chiefId),counts=D.groupCounts(draft.cards),cards=filtered(true),curve=D.getCurve(draft,C),peak=Math.max(1,...curve.map(x=>x.count));return `<div class="site-main">${heading('Forge ton deck','Trouve tes synergies. Prépare ta prochaine chasse.',`<span class="save-indicator">Enregistré dans ce navigateur</span><button class="button" data-do="import-decks">Importer</button><button class="button primary" data-test-deck="${draft.id}" ${!v.valid?'disabled':''}>Tester ce deck ↗</button>`)}<div class="builder-layout"><aside class="builder-sidebar"><h2>Ma collection de decks</h2><div class="deck-select-row"><select id="selected-deck" aria-label="Choisir un deck">${deckOptions(draft.id)}</select><button data-do="new-deck" aria-label="Créer un deck">+</button></div><label class="field">Nom du deck<input id="deck-name" value="${esc(draft.name)}" maxlength="60"></label><label class="field">Chef de chasse<select id="chief-select">${C.cards.filter(c=>c.type==='chief').map(c=>`<option value="${c.id}" ${c.id===draft.chiefId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="deck-chief"><img src="${chief.image}" alt="${esc(chief.name)}"><div><strong>${esc(chief.name)}</strong><small>${chief.colors.map(esc).join(' / ')}</small></div></div><div class="builder-meta"><strong>${draft.cards.length}<span> / 50</span></strong><span>${Object.keys(counts).length} références</span></div><div class="deck-progress"><div style="width:${Math.min(100,draft.cards.length*2)}%"></div></div><p class="builder-status ${v.valid?'valid':''}">${v.valid?`✓ Deck légal · ${v.automated?'Test automatisé disponible':'Prêt pour la table libre'}`:v.errors.map(esc).join('<br>')}</p><div class="mana-curve" aria-label="Courbe des coûts">${curve.map(x=>`<div class="curve-col" title="${x.count} cartes coûtant ${x.label}"><div class="curve-bar" style="height:${x.count/peak*28}px"></div><span>${x.label}</span></div>`).join('')}</div><div class="builder-list">${['large','small','hunter','item','technique'].map(type=>{const entries=Object.entries(counts).filter(([id])=>byId.get(id)?.type===type);return entries.length?`<p class="builder-group">${labels[type]} · ${entries.reduce((a,[,n])=>a+n,0)}</p>${entries.map(([id,n])=>{const c=byId.get(id);return `<div class="builder-row"><span class="mini-cost">${c.cost}</span><button class="card-name" data-detail="${id}">${esc(c.name)}</button><span class="row-quantity">×${n}</span><button class="remove" data-minus="${id}" aria-label="Retirer ${esc(c.name)}">−</button></div>`;}).join('')}`:'';}).join('')||'<p class="small-empty">Ajoute tes premières cartes →</p>'}</div><div class="builder-actions"><button class="button" data-do="export-deck">Exporter</button><button class="button" data-do="duplicate-deck">Dupliquer</button><button class="button quiet danger-quiet" data-do="delete-deck">Supprimer</button></div></aside><section>${filters(true)}<div class="result-line"><span>${cards.length} cartes disponibles</span><span>3 exemplaires maximum · 12 rations automatiques</span></div><div class="card-grid">${cards.map(c=>tile(c,true)).join('')||'<p class="no-result">Aucune carte ne correspond à ces critères.</p>'}</div></section></div></div>`;}
  function playHome(){if(!profile)return gate('À toi de jouer');return `<div class="site-main">${heading('Choisis ta prochaine chasse','Un moment pour tester, ou une partie à partager.')}<div class="play-choice-grid"><section class="play-choice"><span class="feature-label">À TON RYTHME</span><span class="quick-icon">♧</span><h2>Mode test solo</h2><p>Pioche, joue et explore les interactions. Contrôle les décisions des deux camps pour tester tes decks sans attendre un adversaire.</p><button class="button primary" data-go="test">Préparer un test →</button></section><section class="play-choice peer-choice"><span class="feature-label">CONNEXION DIRECTE</span><span class="quick-icon">⇄</span><h2>Chasse entre amis</h2><p>Crée une invitation et échange deux codes avec ton ami. La partie passe ensuite directement entre vos navigateurs.</p><button class="button primary" data-go="enligne">Jouer à deux →</button></section></div>${game?'<p class="info-line"><button class="text-button" data-go="table">Reprendre la table ouverte →</button></p>':''}<p class="fine-print">Les profils et les decks sont locaux à chaque navigateur. Une partie directe demande de garder les deux pages ouvertes.</p></div>`;}
  function modeOptions(){return `<div class="mode-options"><button class="mode-option ${ui.mode==='auto'?'active':''}" data-mode="auto"><b>Test automatisé</b>Le moteur applique les effets des ${supported.size} cartes et Chefs pris en charge.</button><button class="mode-option ${ui.mode==='manual'?'active':''}" data-mode="manual"><b>Table libre</b>Tous les decks. Tu résous les effets avec les outils de la table.</button></div>`;}
  function soloSetup(){if(!profile)return gate('Mode test solo');const saved=store.getGame();return `<div class="site-main">${heading('Le terrain d’entraînement','Teste tes choix en contrôlant les deux camps.')}<section class="setup-panel"><h2>Préparer la table</h2><p>Choisis ton deck et celui du second camp. Aucun adversaire informatique n’intervient : tu peux réfléchir et jouer les deux côtés.</p><div class="setup-fields"><label class="field">Ton deck<select id="solo-left">${deckOptions(ui.leftDeck||decks[0]?.id)}</select></label><label class="field">Deck du second camp<select id="solo-right">${deckOptions(ui.rightDeck||decks[1]?.id||decks[0]?.id)}</select></label></div>${modeOptions()}<label class="field">Qui commence ?<select id="first-player"><option value="random">Tirage au sort</option><option value="0">Ton camp</option><option value="1">Le second camp</option></select></label><div class="setup-note">${ui.mode==='manual'?'La table libre gère les zones, les rations et les blessures. Les capacités, coûts particuliers et choix d’effets se règlent manuellement avec les commandes de carte.':'Le test automatisé utilise uniquement les cartes marquées Auto. Pour les autres cartes, sélectionne la table libre.'}</div><div class="form-row"><button class="button" data-go="decks">Modifier mes decks</button><button class="button primary" data-do="start-solo" ${decks.length?'':'disabled'}>Installer la table</button></div>${saved?'<p class="fine-print"><button class="text-button" data-do="resume-game">Reprendre mon dernier test enregistré →</button></p>':''}</section></div>`;}
  function online(){if(!profile)return gate('Chasse entre amis');const existing=peer?.connected;return `<div class="site-main">${heading('Une chasse entre amis','Deux navigateurs, un échange de codes, puis une connexion directe.')}<div class="network-status ${ui.onlineStatus==='connected'?'connected':['failed','closed','error'].includes(ui.onlineStatus)?'error':''}" id="network-status"><i></i><span>${esc(ui.onlineLabel)}</span></div>${existing?`<div class="peer-active-slot">Vous êtes connectés.${game?' La table est prête.':' La table se prépare…'}<div class="peer-toolbar">${game?'<button class="button primary" data-go="table">Rejoindre la table →</button>':''}<button class="button" data-do="disconnect">Fermer la connexion</button></div></div>`:''}<div class="setup-fields" style="margin:0 0 20px"><label class="field">Le deck que tu vas jouer<select id="online-deck">${deckOptions(ui.leftDeck||decks[0]?.id)}</select></label><div><p class="small-label" style="margin:12px 0 9px">Connexion</p><div class="network-options"><label><input type="radio" name="network" value="internet" ${ui.network==='internet'?'checked':''}> Internet</label><label><input type="radio" name="network" value="lan" ${ui.network==='lan'?'checked':''}> Même réseau, sans STUN</label></div></div></div><div class="peer-layout"><section class="peer-panel"><h2>Créer une partie</h2><p>Tu accueilles la partie. Choisis un mode, puis envoie le code d’invitation à ton ami par le moyen de ton choix.</p>${modeOptions()}<button class="button primary" data-do="create-offer" ${ui.busy||existing?'disabled':''}>${ui.busy?'Préparation…':'Créer mon invitation'}</button>${ui.offer?`<div class="peer-step"><b>1</b>Partage ce code d’invitation</div><textarea class="code-box" readonly aria-label="Code d’invitation">${esc(ui.offer)}</textarea><div class="peer-toolbar"><button class="button" data-copy="offer">Copier le code</button></div><div class="peer-step"><b>2</b>Colle la réponse de ton ami</div><textarea class="code-box" id="answer-input" aria-label="Réponse de ton ami" placeholder="Colle ici son code de réponse…">${esc(ui.answerInput)}</textarea><div class="peer-toolbar"><button class="button primary" data-do="accept-answer" ${ui.busy?'disabled':''}>Connecter la partie</button></div>`:''}</section><section class="peer-panel"><h2>Rejoindre un ami</h2><p>Colle son invitation. Un code de réponse sera créé : renvoie-le à ton ami pour terminer la connexion.</p><div class="peer-step"><b>1</b>Le code reçu</div><textarea class="code-box" id="offer-input" aria-label="Invitation reçue" placeholder="Colle le code d’invitation ici…">${esc(ui.offerInput)}</textarea><div class="peer-toolbar"><button class="button primary" data-do="accept-offer" ${ui.busy||existing?'disabled':''}>Créer ma réponse</button></div>${ui.answer?`<div class="peer-step"><b>2</b>Renvoie ce code à ton ami</div><textarea class="code-box" readonly aria-label="Mon code de réponse">${esc(ui.answer)}</textarea><div class="peer-toolbar"><button class="button" data-copy="answer">Copier ma réponse</button></div><p class="fine-print">Garde cette page ouverte. La partie commencera quand ton ami aura accepté ta réponse.</p>`:''}</section></div><details class="turn-fields"><summary>Connexion avancée · relais personnel facultatif</summary><p class="fine-print">Pour un réseau qui bloque les connexions directes, tu peux fournir ton propre relais TURN. Ces informations restent en mémoire pendant cette session.</p><label class="field">Adresse du relais<input id="turn-urls" value="${esc(ui.turnUrls)}" placeholder="turn:ton-relais:3478"></label><div class="inline-fields"><label class="field">Utilisateur<input id="turn-user" value="${esc(ui.turnUser)}" autocomplete="off"></label><label class="field">Mot de passe du relais<input type="password" id="turn-password" value="${esc(ui.turnPassword)}" autocomplete="off"></label></div></details><p class="peer-footer-note">En mode Internet, STUN aide à trouver une route entre les navigateurs ; ce service ne transporte pas les actions de jeu. Un relais peut être nécessaire sur certains réseaux. Il n’y a ni recherche automatique d’adversaire ni serveur de partie. L’hôte doit rester connecté et arbitre cette partie amicale.</p></div>`;}
  function render(){gameUI?.destroy();gameUI=null;refreshProfile();profileControl();document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===ui.route||(el.dataset.route==='jouer'&&['test','enligne','table'].includes(ui.route))));try{if(ui.route==='table')return renderTable();main.innerHTML=ui.route==='decks'?builder():ui.route==='cartes'?library():ui.route==='jouer'?playHome():ui.route==='test'?soloSetup():ui.route==='enligne'?online():home();}catch(err){main.innerHTML=`<div class="site-main"><p class="form-error">${esc(err.message)}</p><button class="button" data-go="accueil">Retour à l’accueil</button></div>`;console.error(err);}}
  function requireProfile(){if(profile)return true;auth('register');return false;}
  function showModal(title,body,footer='',authDialog=false){modal.className=authDialog?'auth-dialog':'';modal.innerHTML=`<div class="modal-heading"><h2 id="site-modal-title">${title}</h2><button class="icon-button" data-close aria-label="Fermer">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
  function auth(mode='login'){ui.authMode=mode;showModal('Ton profil de chasseur',`<div class="auth-form"><div class="account-tabs"><button data-auth-mode="login" class="${mode==='login'?'active':''}">Se connecter</button><button data-auth-mode="register" class="${mode==='register'?'active':''}">Créer un profil</button></div><form id="auth-form"><div id="auth-error"></div><label class="field">Pseudo<input name="username" id="auth-username" autocomplete="username" minlength="3" maxlength="24" required placeholder="Ton nom de chasseur"></label><label class="field">Mot de passe<input name="password" id="auth-password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="8" maxlength="256" required placeholder="8 caractères minimum"></label>${mode==='register'?'<label class="field">Confirmer le mot de passe<input id="auth-confirm" type="password" autocomplete="new-password" minlength="8" maxlength="256" required></label>':''}<p class="auth-help">Profil local à ce navigateur. Aucun email, aucun compte central. Tes decks restent sur cet appareil ; exporte-les pour les conserver ailleurs.</p><button class="button primary full" type="submit" id="auth-submit">${mode==='register'?'Créer mon profil':'Entrer dans la Guilde'}</button></form></div>`,'',true);}
  function account(){if(!profile)return auth('login');showModal('Ton espace à la Guilde',`<div class="profile-summary"><span class="profile-avatar">${esc(profile.username.slice(0,2).toUpperCase())}</span><h3>${esc(profile.username)}</h3><p>${decks.length} deck${decks.length>1?'s':''} dans ce navigateur</p></div><div class="profile-menu"><button class="button primary" data-go="decks" data-close>Retrouver mes decks</button><button class="button" data-do="export-all">Exporter tous mes decks</button><button class="button quiet" data-do="logout">Se déconnecter</button></div><p class="auth-help">Ce profil ne se synchronise pas entre appareils. Le mot de passe n’est pas envoyé à un serveur.</p>`,'',true);}
  function detail(id){const c=byId.get(id);if(!c)return;showModal('À la loupe',`<div class="detail-layout"><img class="detail-image" src="${c.image}" alt="${esc(c.name)}"><div><p class="detail-id">MhFG · ${esc(c.id)}</p><h3>${esc(c.name)}</h3><p class="detail-meta">${esc(c.typeLabel)}${c.subtypes.length?' / '+c.subtypes.map(esc).join(' / '):''}<br>${c.colors.map(esc).join(' / ')}${c.cost!=null?' · Coût '+c.cost:''}${c.force!=null?' · Force '+c.force:''}${c.hp!=null?' · PV '+c.hp:''}</p><p class="effect-text">${esc(c.text)}</p><p class="detail-status ${supported.has(c.id)?'':'library'}">${supported.has(c.id)?'Effet pris en charge dans le test automatisé.':'Disponible dans le deck builder et sur la table libre. Les joueurs résolvent cet effet manuellement.'}</p></div></div>`);}
  function about(){showModal('Règles & fonctionnement',`<div class="rules-grid"><section class="rules-card"><h3>Le but de la chasse</h3><p>Atteins 6 points en tuant des Grands Monstres. Les blessures restent sur les cartes. Les Petits Monstres et les Chasseurs ne rapportent aucun point. Le Chef ne combat pas.</p></section><section class="rules-card"><h3>Préparer son deck</h3><p>50 cartes, 3 exemplaires maximum et les couleurs de ton Chef. Les 12 rations sont ajoutées automatiquement. Chaque début de tour ajoute 1 ration.</p></section><section class="rules-card"><h3>Réflexe & Interposition</h3><p>Le joueur actif peut jouer un Réflexe en premier. S’il passe, l’autre joueur peut répondre. La pile se résout du dernier effet au premier après deux passages. Une seule Interposition peut rediriger une attaque.</p></section><section class="rules-card"><h3>Tes sauvegardes</h3><p>Profils et decks sont conservés localement dans le navigateur. Effacer les données du site les supprime. L’export permet de les emporter ailleurs ; aucun email ne permet de récupérer un mot de passe oublié.</p></section><section class="rules-card wide"><h3>Les deux tables</h3><p>Le test automatisé applique les effets des ${supported.size} cartes et Chefs déjà programmés. La table libre accepte tout le catalogue : les joueurs utilisent ses outils pour résoudre les effets et les coûts particuliers. En solo, tu pilotes les deux camps ; il n’y a pas encore d’adversaire informatique.</p></section><section class="rules-card wide"><h3>Documents de référence</h3><p>Données issues de <a href="${esc(C.sources.cards.url)}" target="_blank" rel="noopener">Liste Carte Propre</a> et des <a href="${esc(C.sources.rules.url)}" target="_blank" rel="noopener">règles du jeu</a>. Illustrations finales françaises du créateur. Aucun ancien catalogue de cartes n’est utilisé.</p></section></div>`);}
  function download(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function starterDecks(){for(const d of E.STARTER_DECKS)store.saveDeck({name:d.name,chiefId:d.chiefId,cards:d.cards});decks=store.listDecks();loadDraft(decks[0]?.id);}
  function mutateDeck(id,amount){if(!draft)return;const c=byId.get(id);if(!c||['chief','token'].includes(c.type))return;if(amount>0){if(draft.cards.length>=50)return toast('Le deck contient déjà 50 cartes. Retire une carte pour en ajouter une autre.');if(draft.cards.filter(x=>x===id).length>=3)return toast('Trois exemplaires maximum par carte.');if(!c.colors.every(x=>byId.get(draft.chiefId).colors.includes(x)))return toast('Cette carte ne correspond pas aux couleurs du Chef.',true);draft.cards.push(id);}else{const i=draft.cards.lastIndexOf(id);if(i>=0)draft.cards.splice(i,1);}saveDraft();render();}
  function chosenEngine(mode){return mode==='manual'?T:E;}
  function checkPlayable(deck,mode){if(!deck)throw Error('Choisis un deck dans le deck builder.');const v=validation(deck);if(!v.valid)throw Error(v.errors.join(' '));if(mode==='auto'&&!v.automated)throw Error('Ce deck contient des effets qui ne sont pas encore automatisés. Choisis la table libre pour le jouer.');}
  function saveSolo(){if(!game||game.online||!profile)return;store.saveGame({format:'mh-tcg-site-game',version:1,catalogVersion:C.version,mode:game.mode,state:game.state});}
  function startSolo(){const left=getDeck(document.getElementById('solo-left')?.value),right=getDeck(document.getElementById('solo-right')?.value);checkPlayable(left,ui.mode);checkPlayable(right,ui.mode);const first=document.getElementById('first-player')?.value,firstPlayer=first==='random'?crypto.getRandomValues(new Uint8Array(1))[0]%2:Number(first||0),engine=chosenEngine(ui.mode);disconnect(true);game={online:false,mode:ui.mode,engine,state:engine.createGame(C,{decks:[left,right],names:[profile.username,'Camp d’entraînement'],seed:crypto.getRandomValues(new Uint32Array(1))[0],firstPlayer})};saveSolo();route('table');}
  function resumeGame(){const data=store.getGame();if(!data||data.format!=='mh-tcg-site-game'||data.version!==1||data.catalogVersion!==C.version||!data.state?.players||data.state.players.length!==2)throw Error('Aucun test compatible à reprendre.');const engine=chosenEngine(data.mode);engine.getActions(data.state,C);disconnect(true);game={online:false,mode:data.mode,engine,state:data.state};route('table');}
  function renderTable(){if(!game){main.innerHTML=`<div class="site-main">${heading('La table est libre','Choisis un mode de jeu pour commencer.')}<button class="button primary" data-go="jouer">Préparer une partie</button></div>`;return;}main.innerHTML=`<div class="site-main"><div class="match-top"><p>${game.online?`⇄ Partie directe · <strong>${ui.onlineStatus==='connected'?'Connecté':'Connexion interrompue'}</strong>`:'♧ Mode test solo · Tu contrôles les deux camps'}</p><button class="text-button" data-do="about">Aide & règles</button></div>${game.mode==='manual'?'<div class="manual-notice">Table libre : les effets des cartes et les coûts particuliers sont à résoudre manuellement. Les outils de carte permettent de modifier les blessures, la Force, les marqueurs et les zones.</div>':''}<div id="game-mount" class="game-mount"></div></div>`;gameUI=MHGameUI.create({container:document.getElementById('game-mount'),catalog:C,engine:game.engine,onAction:actGame,onExit:()=>route('jouer'),onSave:()=>{if(game.online)toast('Garde cette page ouverte pour continuer la partie directe.');else{saveSolo();toast('Test enregistré dans ton profil local.');}},onExport:exportGame,onError:err=>toast(err.message||String(err),true),localPlayer:game.online?game.localPlayer:null,mode:game.mode});updateGameUI();}
  function updateGameUI(){if(!gameUI||!game)return;if(game.online){const packet=game.localPlayer===0?hostMatch?.viewFor(0):game.packet;if(packet)gameUI.update(packet.state,peer?.connected?packet.actions:[]);}else gameUI.update(game.state,game.engine.getActions(game.state,C));}
  function actGame(action){try{if(game.online){if(!peer?.connected)throw Error('La connexion avec ton ami est interrompue.');if(game.localPlayer===0){hostMatch.apply(0,action,hostMatch.revision);sendState();updateGameUI();}else{const intent={id:action.id,type:action.type};if(Array.isArray(action.targetIds))intent.targetIds=action.targetIds;if(action.choiceId!==undefined)intent.choiceId=action.choiceId;peer.send({type:'action',revision,action:intent});}}else{game.state=game.engine.dispatch(game.state,action,C);saveSolo();updateGameUI();}}catch(err){toast(err.message,true);}}
  function exportGame(){if(!game)return;download(game.online?{format:'mh-tcg-personal-match-view',version:1,packet:game.localPlayer===0?hostMatch.viewFor(0):game.packet}:{format:'mh-tcg-site-game',version:1,catalogVersion:C.version,mode:game.mode,state:game.state},game.online?'MH-TCG-vue-de-partie.json':'MH-TCG-test-solo.json');}
  function updateNetworkStatus(status,label){ui.onlineStatus=status;ui.onlineLabel=label;const el=document.getElementById('network-status');if(el){el.className='network-status'+(status==='connected'?' connected':['failed','closed','error'].includes(status)?' error':'');el.innerHTML=`<i></i><span>${esc(label)}</span>`;}if(game?.online)updateGameUI();}
  function disconnect(silent=false){const old=peer;peer=null;old?.close();hostMatch=null;revision=-1;ui.onlineRole=null;ui.onlineStatus='idle';ui.onlineLabel='Aucune connexion en cours.';ui.offer='';ui.answer='';if(game?.online){gameUI?.destroy();gameUI=null;game=null;}if(!silent){toast('La connexion directe a été fermée.');render();}}
  function networkOptions(){const o={mode:ui.network};if(ui.turnUrls.trim()){if(!/^turns?:/i.test(ui.turnUrls.trim()))throw Error('L’adresse du relais doit commencer par turn: ou turns:.');o.turn={urls:ui.turnUrls.trim(),username:ui.turnUser,credential:ui.turnPassword};}return o;}
  function newPeer(role){disconnect(true);ui.onlineRole=role;const session=new MHP2P.PeerSession({onStatus:(status,label)=>{if(peer===session)updateNetworkStatus(status,label);},onMessage:message=>{if(peer===session)handlePeer(message);},onOpen:()=>{if(peer!==session)return;updateNetworkStatus('connected','Connexion directe établie. Préparation de la table…');if(role==='guest')session.send({type:'hello',nickname:profile.username,deck:clone(getDeck(ui.leftDeck)),catalogVersion:C.version});},onClose:reason=>{if(peer===session&&ui.onlineStatus!=='failed')updateNetworkStatus('closed',reason||'Ton ami a quitté la connexion. La partie est suspendue.');}});peer=session;return session;}
  function sendState(){if(!peer?.connected||!hostMatch)return;peer.send(hostMatch.viewFor(1));}
  function handlePeer(message){try{if(!message||typeof message!=='object')return;if(ui.onlineRole==='host'&&message.type==='hello'){if(hostMatch)return;if(message.catalogVersion!==C.version)throw Error('Les deux navigateurs doivent utiliser la même version du catalogue.');if(typeof message.nickname!=='string'||message.nickname.length<1||message.nickname.length>24)throw Error('Le pseudo reçu est invalide.');checkPlayable(message.deck,ui.onlineMode);const own=getDeck(ui.leftDeck);checkPlayable(own,ui.onlineMode);const engine=chosenEngine(ui.onlineMode),state=engine.createGame(C,{decks:[own,message.deck],names:[profile.username,message.nickname],seed:crypto.getRandomValues(new Uint32Array(1))[0],firstPlayer:crypto.getRandomValues(new Uint8Array(1))[0]%2});hostMatch=new MHMatch.HostMatch({catalog:C,engine,initialState:state});game={online:true,mode:ui.onlineMode,engine,localPlayer:0};sendState();updateNetworkStatus('connected','Connexion directe établie. La table est prête.');route('table');return;}if(ui.onlineRole==='host'&&message.type==='action'){if(!hostMatch)throw Error('La table n’est pas encore prête.');hostMatch.apply(1,message.action,message.revision);sendState();updateGameUI();return;}if(ui.onlineRole==='guest'&&message.type==='state'){if(!Number.isInteger(message.revision)||message.revision<0||message.revision<revision||!message.state?.players||message.state.players.length!==2||!Array.isArray(message.actions))throw Error('L’état de partie reçu est invalide.');if(message.state.catalogVersion!==C.version)throw Error('Le catalogue de ton ami utilise une autre version.');revision=message.revision;const isFirst=!game?.online;game={online:true,mode:message.engineMode==='manual'?'manual':'auto',engine:chosenEngine(message.engineMode),localPlayer:1,packet:message};updateNetworkStatus('connected','Connexion directe établie. La table est prête.');if(isFirst)route('table');else updateGameUI();return;}if(message.type==='error')toast(typeof message.message==='string'?message.message.slice(0,500):'Ton ami ne peut pas poursuivre cette action.',true);}catch(err){toast(err.message,true);if(peer?.connected){try{peer.send({type:'error',message:err.message});if(hostMatch)sendState();}catch{}}}}
  async function signal(kind){if(!requireProfile())return;if(ui.busy)throw Error('La connexion est déjà en cours de préparation.');ui.leftDeck=document.getElementById('online-deck')?.value||ui.leftDeck||decks[0]?.id;const d=getDeck(ui.leftDeck);if(!d)throw Error('Crée ou importe un deck avant de lancer une partie.');if(kind==='offer')checkPlayable(d,ui.mode);else if(kind==='answer')checkPlayable(d,'manual');const options=networkOptions();ui.onlineMode=ui.mode;const input=kind==='answer'?ui.offerInput:ui.answerInput;ui.busy=true;if(ui.route==='enligne')render();try{if(kind==='offer'){const p=newPeer('host');ui.offer=await p.createOffer(options);}else if(kind==='answer'){const p=newPeer('guest');ui.answer=await p.acceptOffer(input,options);}else{if(!peer||!ui.offer)throw Error('Crée d’abord une invitation.');await peer.acceptAnswer(input);}}finally{ui.busy=false;if(ui.route==='enligne')render();}}
  async function command(name){try{switch(name){case'account':account();break;case'register':auth('register');break;case'about':about();break;case'logout':disconnect(true);game=null;draft=null;store.logout();modal.close();route('accueil');render();toast('Tu es déconnecté. Tes decks restent dans ce navigateur.');break;case'new-deck':newDeck();break;case'starter-decks':starterDecks();render();break;case'export-all':download(store.exportProfile(),'MH-TCG-mes-decks.json');break;case'export-deck':download({format:'mh-tcg-deck',version:1,deck:{name:draft.name,chiefId:draft.chiefId,cards:draft.cards}},'MH-TCG-'+draft.name.replace(/[^\p{L}\p{N} -]/gu,'')+'.json');break;case'import-decks':if(requireProfile())document.getElementById('deck-upload').click();break;case'duplicate-deck':draft=store.saveDeck({name:draft.name+' · copie',chiefId:draft.chiefId,cards:draft.cards});decks=store.listDecks();ui.deckId=draft.id;render();toast('Une copie de ton deck a été créée.');break;case'delete-deck':showModal('Supprimer ce deck ?',`<p>Le deck « ${esc(draft.name)} » sera retiré de ce profil. Tu peux l’exporter avant de le supprimer.</p>`,'<button class="button" data-close>Conserver</button><button class="button danger" data-do="confirm-delete">Supprimer le deck</button>');break;case'confirm-delete':store.deleteDeck(draft.id);decks=store.listDecks();loadDraft(decks[0]?.id);modal.close();render();break;case'start-solo':startSolo();break;case'resume-game':resumeGame();break;case'create-offer':await signal('offer');break;case'accept-offer':await signal('answer');break;case'accept-answer':await signal('final');break;case'disconnect':disconnect();break;}}catch(err){ui.busy=false;toast(err.message,true);}}
  document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b||b.closest('.game-mount')||b.closest('.game-ui-shell')||b.closest('[data-mh-game-ui]'))return;if(b.dataset.go){if(b.hasAttribute('data-close'))modal.close();route(b.dataset.go);return;}if(b.hasAttribute('data-close'))return modal.close();if(b.dataset.do)return void command(b.dataset.do);if(b.dataset.authMode)return auth(b.dataset.authMode);if(b.dataset.detail)return detail(b.dataset.detail);if(b.dataset.editDeck){loadDraft(b.dataset.editDeck);route('decks');return;}if(b.dataset.testDeck){const d=getDeck(b.dataset.testDeck);ui.leftDeck=d?.id;ui.mode=validation(d).automated?'auto':'manual';route('test');return;}if(b.dataset.color!==undefined){ui.color=b.dataset.color;render();return;}if(b.dataset.plus)return mutateDeck(b.dataset.plus,1);if(b.dataset.minus)return mutateDeck(b.dataset.minus,-1);if(b.dataset.mode){ui.mode=b.dataset.mode;render();return;}if(b.dataset.copy){const text=ui[b.dataset.copy];if(!text)return;void navigator.clipboard.writeText(text).then(()=>toast('Code copié. Envoie-le à ton ami.')).catch(()=>toast('La copie automatique est indisponible. Sélectionne et copie le code dans le champ.',true));}});
  document.addEventListener('input',event=>{const t=event.target;if(t.id==='card-search'){ui.search=t.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=t.selectionStart;render();const input=document.getElementById('card-search');input?.focus();if(input?.setSelectionRange)input.setSelectionRange(pos,pos);},160);return;}if(t.id==='deck-name'&&draft){draft.name=t.value;saveDraft();return;}const fields={'offer-input':'offerInput','answer-input':'answerInput','turn-urls':'turnUrls','turn-user':'turnUser','turn-password':'turnPassword'};if(fields[t.id])ui[fields[t.id]]=t.value;});
  document.addEventListener('change',event=>{const t=event.target;if(t.id==='selected-deck'){loadDraft(t.value);render();}if(t.id==='chief-select'){draft.chiefId=t.value;saveDraft();render();toast('Chef modifié. Les cartes déjà ajoutées sont conservées ; vérifie leurs couleurs.');}const fields={'extension-filter':'extension','type-filter':'type','cost-filter':'cost','sort-filter':'sort'};if(fields[t.id]){ui[fields[t.id]]=t.value;render();}if(t.id==='compatible-filter'){ui.compatible=t.checked;render();}if(['solo-left','online-deck'].includes(t.id))ui.leftDeck=t.value;if(t.id==='solo-right')ui.rightDeck=t.value;if(t.name==='network'){ui.network=t.value;}});
  document.addEventListener('submit',async event=>{if(event.target.id!=='auth-form')return;event.preventDefault();const button=document.getElementById('auth-submit'),error=document.getElementById('auth-error'),username=document.getElementById('auth-username').value,password=document.getElementById('auth-password').value;button.disabled=true;button.textContent='Un instant…';error.innerHTML='';try{if(ui.authMode==='register'&&password!==document.getElementById('auth-confirm').value)throw Error('Les deux mots de passe ne correspondent pas.');if(ui.authMode==='register'){await store.register(username,password);refreshProfile();starterDecks();}else await store.login(username,password);refreshProfile();draft=null;modal.close();render();toast('Bienvenue à la Guilde, '+profile.username+'.');}catch(err){error.innerHTML=`<p class="form-error">${esc(err.message)}</p>`;button.disabled=false;button.textContent=ui.authMode==='register'?'Créer mon profil':'Entrer dans la Guilde';}});
  document.getElementById('deck-upload').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>2*1024*1024)throw Error('Ce fichier est trop volumineux pour contenir des decks.');const data=JSON.parse(await file.text()),incoming=Array.isArray(data.decks)?data.decks:data.deck?[data.deck]:Array.isArray(data)?data:null;if(!incoming?.length||incoming.length>200)throw Error('Le fichier ne contient pas de decks compatibles.');for(const d of incoming){if(!byId.get(d.chiefId)||byId.get(d.chiefId).type!=='chief'||!Array.isArray(d.cards)||d.cards.length>100||d.cards.some(id=>!byId.has(id)||['chief','token'].includes(byId.get(id).type)))throw Error('Une carte ou un Chef du fichier ne fait pas partie du catalogue actuel.');}const imported=store.importDecks(incoming);decks=store.listDecks();loadDraft(imported[0]?.id||decks.at(-1)?.id);ui.route='decks';location.hash='decks';render();toast('Decks importés dans ton profil local.');}catch(err){toast(err.message,true);}});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1).split('?')[0];ui.route=['accueil','cartes','decks','jouer','test','enligne','table'].includes(next)?next:'accueil';render();window.scrollTo(0,0);});
  window.addEventListener('beforeunload',()=>{try{saveSolo();}catch{}peer?.close();});
  refreshProfile();ui.route=['accueil','cartes','decks','jouer','test','enligne','table'].includes(location.hash.slice(1))?location.hash.slice(1):'accueil';render();
})();
